/**
 * Shared paragraphs.
 *
 * @param string $to   «в Китай», «на Бали» …
 * @param string $name Country name.
 * @return array<string,array<int,string>>
 */
function zhiraf_ufa_moscow_common_sections( $to, $name ) {
	return array(
		'price'  => array(
			sprintf( __( 'Цена «от» на карточках выше — минимальная стоимость тура %s у туроператора «Библио-Глобус» за 2 взрослых: перелёт из Москвы туда и обратно и проживание в отеле на указанное число ночей с указанным типом питания (BB — завтраки, HB — полупансион, FB — полный пансион, AI — всё включено, AO — без питания). На странице — по одному самому дешёвому отелю на курорт, чтобы было видно разброс цен по направлению.', 'zhiraf-ufa' ), $to ),
			__( 'Цена рассчитана туроператором на дату, указанную рядом с ней. Если тур продаётся в валюте, пересчёт идёт по курсу туроператора на день оплаты, поэтому итоговая стоимость фиксируется только при бронировании. Трансфер, медицинская страховка, норма багажа и сборы зависят от конкретного тура — менеджер проверит их в описании тура у туроператора до оплаты.', 'zhiraf-ufa' ),
		),
		'flight' => array(
			sprintf( __( 'Все цены по направлению %s рассчитаны для вылета из Москвы. Перелёт Уфа — Москва — Уфа в стоимость не входит: его покупают отдельно. Если билеты оформлены отдельно от тура, при задержке первого рейса перевозчик второго не обязан ждать, поэтому между прилётом в Москву и вылетом по туру стоит закладывать запас времени, а иногда — прилетать накануне.', 'zhiraf-ufa' ), $name ),
			__( 'Авиакомпания тура указана на каждой карточке. Пометка «без багажа» означает тариф без багажа в стоимости. Если на карточке указаны две авиакомпании, менеджер уточнит маршрут и рейсы в каждую сторону до бронирования.', 'zhiraf-ufa' ),
		),
		'how'    => array(
			__( 'Оставьте заявку или позвоните: менеджер проверит у туроператора «Библио-Глобус» наличие мест на ваши даты, состав тура и итоговую цену, подскажет по перелёту из Уфы в Москву и оформит договор. Цены и наличие мест меняются в реальном времени, поэтому подтверждаем их в момент бронирования.', 'zhiraf-ufa' ),
		),
